package ug.audiocity.studio;
import java.io.*;import java.nio.file.*;import java.security.*;import java.util.*;import java.util.zip.*;import org.json.*;
/** User-owned WAV/ZIP drum libraries. Each chosen sound has a portable, content-addressed snapshot. */
public final class UserDrumPacks {
 private UserDrumPacks(){}
 private static final long MAX_TOTAL=512L*1024*1024,MAX_WAV=32L*1024*1024;
 public static final class Sound {public final String file,name,category;Sound(String f,String n,String c){file=f;name=n;category=c;}}
 public static final class Info {public final String id,name;public final List<Sound> sounds;Info(String i,String n,List<Sound> s){id=i;name=n;sounds=Collections.unmodifiableList(s);}}
 public static boolean validSampleFile(String file){return file!=null&&file.matches("instrument-[0-9a-f]{64}\\.acpack");}
 private static File home(File app)throws IOException{File home=new File(app,"drum_packs");if(!home.isDirectory()&&!home.mkdirs())throw new IOException("Cannot create drum pack library.");return home;}
 private static String title(String name){String t=name==null?"Imported drums":name.trim();if(t.isEmpty())t="Imported drums";return t.substring(0,Math.min(80,t.length()));}
 private static void delete(File f){if(f.isDirectory()){File[] files=f.listFiles();if(files!=null)for(File child:files)delete(child);}f.delete();}
 private static String hash(byte[] bytes)throws IOException{try{MessageDigest d=MessageDigest.getInstance("SHA-256");StringBuilder s=new StringBuilder();for(byte b:d.digest(bytes))s.append(String.format(Locale.US,"%02x",b&255));return s.toString();}catch(NoSuchAlgorithmException e){throw new IOException(e);}}
 private static void path(String p)throws IOException{if(p.isEmpty()||p.length()>240||p.startsWith("/")||p.contains(":")||p.indexOf(0)>=0)throw new IOException("Unsafe path in drum ZIP.");for(String part:p.split("/",-1))if(part.isEmpty()||part.equals(".")||part.equals(".."))throw new IOException("Unsafe path in drum ZIP.");}
 private static String category(String name){String n=name.toLowerCase(Locale.US);if(n.contains("kick")||n.contains("bass drum"))return "Kick";if(n.contains("snare"))return "Snare";if(n.contains("clap")||n.contains("snap"))return "Clap";if(n.contains("hat")||n.contains("hihat")||n.contains(" hi-hat"))return "Hat";if(n.contains("perc")||n.contains("conga")||n.contains("bongo")||n.contains("shak")||n.contains("maraca")||n.contains("tom")||n.contains("rim")||n.contains("stick"))return "Percussion";return "Other";}
 private static void collect(File root,File dir,List<File> out){File[] entries=dir.listFiles();if(entries==null)return;Arrays.sort(entries,Comparator.comparing(File::getName));for(File f:entries)if(f.isDirectory())collect(root,f,out);else out.add(f);}
 public static Info install(InputStream input,String filename,File app)throws IOException{
  File library=home(app),staging=Files.createTempDirectory(library.toPath(),".import-").toFile(),raw=new File(staging,"raw"),ready=new File(staging,"ready");raw.mkdir();ready.mkdir();
  String lower=filename==null?"":filename.toLowerCase(Locale.US);try{
   if(lower.endsWith(".wav")){try(OutputStream out=new FileOutputStream(new File(raw,"sample.wav"))){byte[] b=new byte[32768];int n;long size=0;while((n=input.read(b))!=-1){size+=n;if(size>MAX_WAV)throw new IOException("A drum WAV can be at most 32 MB.");out.write(b,0,n);}}}
   else if(lower.endsWith(".zip")){try(ZipInputStream zip=new ZipInputStream(new BufferedInputStream(input))){ZipEntry e;Set<String> seen=new HashSet<>();int count=0;long total=0;byte[] b=new byte[32768];while((e=zip.getNextEntry())!=null){if(++count>3000)throw new IOException("Too many files in this drum pack.");String name=e.getName().replace('\\','/');if(e.isDirectory()&&name.endsWith("/"))name=name.substring(0,name.length()-1);path(name);if(!seen.add(name))throw new IOException("Duplicate path in drum ZIP.");if(e.isDirectory()){zip.closeEntry();continue;}String ext=name.toLowerCase(Locale.US);boolean wav=ext.endsWith(".wav")&&!name.startsWith("__MACOSX/"),text=(ext.endsWith(".txt")||ext.endsWith(".md"))&&!name.startsWith("__MACOSX/");File outFile=new File(raw,name);if(wav||text){if(!outFile.getParentFile().isDirectory()&&!outFile.getParentFile().mkdirs())throw new IOException("Cannot create sample folder.");}long item=0;try(OutputStream out=wav||text?new FileOutputStream(outFile):new OutputStream(){public void write(int value){}public void write(byte[] b,int off,int length){}}){int n;while((n=zip.read(b))!=-1){item+=n;total+=n;if(total>MAX_TOTAL||wav&&item>MAX_WAV||text&&item>1048576)throw new IOException("Drum pack exceeds limits: 512 MB total, 32 MB per WAV, 1 MB per text file.");out.write(b,0,n);}}zip.closeEntry();}}}
   else throw new IOException("Choose a WAV or a ZIP containing WAV samples. Extract RAR/7z packs first.");
   List<File> files=new ArrayList<>();collect(raw,raw,files);StringBuilder notes=new StringBuilder();for(File file:files)if(file.getName().toLowerCase(Locale.US).matches(".*\\.(txt|md)$")){String rel=raw.toURI().relativize(file.toURI()).getPath();File target=new File(ready,"notes/"+rel);target.getParentFile().mkdirs();Files.copy(file.toPath(),target.toPath());if(notes.length()<10000){String contents=new String(Files.readAllBytes(file.toPath()),"UTF-8");notes.append('\n').append(rel).append('\n').append(contents,0,Math.min(2000,contents.length()));}}
   long converted=0;String packName=title(filename==null?null:filename.replaceFirst("(?i)\\.(zip|wav)$",""));JSONArray samples=new JSONArray();for(File file:files)if(file.getName().toLowerCase(Locale.US).endsWith(".wav")){if(samples.length()>=1000)throw new IOException("A drum pack can contain at most 1000 WAV samples.");String relative=raw.toURI().relativize(file.toURI()).getPath();String label=title(lower.endsWith(".wav")?filename.replaceFirst("(?i)\\.wav$",""):relative.replaceFirst("(?i)\\.wav$",""));float[] pcm=SampledInstruments.readWav(file);SampledInstruments.Pack sample=new SampledInstruments.Pack(label,"Imported by user: "+packName+" / "+relative+notes.toString(),new SampledInstruments.Region[]{new SampledInstruments.Region(0,127,1,127,60,0,0,false,1,pcm,240)});String packed=InstrumentArchive.write(sample,ready);converted+=new File(ready,packed).length();if(converted>MAX_TOTAL)throw new IOException("Converted drum pack exceeds 512 MB. Split it into smaller packs.");samples.put(new JSONObject().put("file",packed).put("name",label).put("category",category(lower.endsWith(".wav")?filename:relative)));}
   if(samples.length()==0)throw new IOException("This pack contains no supported WAV samples.");byte[] index=new JSONObject().put("schema",1).put("name",packName).put("sounds",samples).toString().getBytes("UTF-8");Files.write(new File(ready,"index.json").toPath(),index);String id="pack-"+hash(index);File destination=new File(library,id);if(!destination.exists())Files.move(ready.toPath(),destination.toPath());return read(destination,id);
  }catch(JSONException e){throw new IOException("Invalid drum pack index",e);}finally{delete(staging);}
 }
 private static Info read(File folder,String id)throws IOException{if(!id.matches("pack-[0-9a-f]{64}"))throw new IOException("Invalid drum pack ID.");File index=new File(folder,"index.json");if(index.length()>1048576)throw new IOException("Drum pack index is too large.");try{JSONObject json=new JSONObject(new String(Files.readAllBytes(index.toPath()),"UTF-8"));JSONArray entries=json.getJSONArray("sounds");if(entries.length()<1||entries.length()>1000)throw new IOException("Invalid sample count.");List<Sound> sounds=new ArrayList<>();for(int i=0;i<entries.length();i++){JSONObject item=entries.getJSONObject(i);String file=item.getString("file");if(!validSampleFile(file)||!new File(folder,file).isFile())throw new IOException("Drum sample is missing.");sounds.add(new Sound(file,title(item.getString("name")),item.optString("category","Other")));}return new Info(id,title(json.getString("name")),sounds);}catch(JSONException e){throw new IOException("Invalid drum pack index",e);}}
 public static List<Info> list(File app)throws IOException{File[] dirs=home(app).listFiles();List<Info> result=new ArrayList<>();if(dirs!=null){Arrays.sort(dirs,Comparator.comparing(File::getName));for(File dir:dirs)if(dir.isDirectory()&&dir.getName().startsWith("pack-"))try{result.add(read(dir,dir.getName()));}catch(IOException ignored){}}result.sort(Comparator.comparing(p->p.name.toLowerCase(Locale.US)));return result;}
 private static SampledInstruments.Pack single(File folder,String file)throws IOException{if(!validSampleFile(file))throw new IOException("Invalid personal drum sample reference.");SampledInstruments.Pack p=InstrumentArchive.read(folder,file);if(p.regions.length!=1||p.regions[0].loop)throw new IOException("Choose a one-shot WAV drum sample.");return p;}
 public static float[] load(File project,File app,String file)throws IOException{if(!validSampleFile(file))throw new IOException("Invalid personal drum sample reference.");if(project!=null&&new File(project,file).isFile())return single(project,file).regions[0].pcm;for(Info pack:list(app)){File folder=new File(home(app),pack.id);if(new File(folder,file).isFile()){if(project!=null)copy(folder,project,file);return single(folder,file).regions[0].pcm;}}throw new IOException("This personal drum sound is missing. Import its original pack again or choose a replacement on the lane.");}
 public static float[] preview(File app,Info pack,Sound sound)throws IOException{if(!pack.id.matches("pack-[0-9a-f]{64}"))throw new IOException("Invalid drum pack ID.");return single(new File(home(app),pack.id),sound.file).regions[0].pcm;}
 public static float[] choose(File app,File project,Info pack,Sound sound)throws IOException{if(!pack.id.matches("pack-[0-9a-f]{64}"))throw new IOException("Invalid drum pack ID.");File folder=new File(home(app),pack.id);float[] pcm=single(folder,sound.file).regions[0].pcm;copy(folder,project,sound.file);return pcm;}
 private static void copy(File source,File project,String file)throws IOException{if(project==null||new File(project,file).isFile())return;File temp=File.createTempFile("drum-copy-",".tmp",project);try{Files.copy(new File(source,file).toPath(),temp.toPath(),StandardCopyOption.REPLACE_EXISTING);Files.move(temp.toPath(),new File(project,file).toPath(),StandardCopyOption.REPLACE_EXISTING);}finally{temp.delete();}}
 public static Set<String> projectFiles(Core.Session project){Set<String> result=new LinkedHashSet<>();for(PatternLibrary.Entry entry:project.patterns)add(result,BeatPilotDrumPattern.decode(entry.data));for(Core.Clip clip:InstrumentArchive.clips(project))if(clip.drumPattern!=null&&clip.drumPattern.startsWith("v5|"))add(result,BeatPilotDrumPattern.decode(clip.drumPattern));return result;}
 private static void add(Set<String> files,BeatPilotDrumPattern p){for(int lane=0;lane<8;lane++)if(p.imported(lane))files.add(p.userFile(lane));}
}
